#include <iostream>
#include <vector>
using namespace std;

int main() {
  int n;
  cin >> n;
  vector<int> a(n);
  for (int& x : a) {
    cin >> x;
  }
  int ans = 0;
  for (int i = 0; i < n; ++i) {
    bool appeared = false;
    for (int j = 0; j < i; ++j) {
      if (a[i] == a[j]) {
        appeared = true;
      }
    }
    if (!appeared) {
      ans += 1;
    }
  }
  cout << ans << '\n';
}

