#include <iostream>
#include <vector>
#include <algorithm>
#include <iterator>
using namespace std;

int main() {
  int n;
  cin >> n;
  vector<int> a(n);
  for (int& x : a) {
    cin >> x;
  }
  sort(begin(a), end(a));
  int ans = 1;
  for (int i = 0; i < n - 1; ++i) {
    if (a[i] != a[i + 1]) {
      ans += 1;
    }
  }
  cout << ans << '\n';
}
